/**
 * Shared runtime for List View Studio pieces. It runs as one update-only CustomEffect
 * ("List logic", EXODE_KEEP_LIVE) beside native row layers. Each piece prepends
 *   var LV = {...config};  function layout(i, d, k) {...}  [function frame(k) {...}]
 * and this runtime drives gestures, inertia, snap, springs and physics, then asks
 * layout() where every row sits. The same code bakes the design-view frame at insert
 * time and animates the plugin's thumbnails, so what you see is what plays.
 *
 * The .bexode compiler minifies effect code: explicit semicolons, block comments
 * only, and never two minus signs in a row.
 */
export declare const LIST_VIEW_RUNTIME: string;
